B.aqg=s(["\u0642\u0645 \u0628\u0639\u0645\u0644 \u0637\u064a\u0628 \u0627\u0644\u064a\u0648\u0645 \u062f\u0648\u0646 \u0623\u0646 \u064a\u0639\u0644\u0645 \u0628\u0647 \u0623\u062d\u062f.","\u0627\u0639\u062a\u0630\u0631 \u0644\u0634\u062e\u0635 \u0623\u062e\u0637\u0623\u062a \u0641\u064a \u062d\u0642\u0647\u060c \u0648\u0644\u0648 \u0643\u0627\u0646 \u0627\u0644\u062e\u0637\u0623 \u0635\u063a\u064a\u0631\u064b\u0627.","\u0623\u0648\u0641\u0650 \u0628\u0648\u0639\u062f \u0635\u063a\u064a\u0631 \u0642\u0637\u0639\u062a\u0647 \u0644\u0623\u062d\u062f\u0647\u0645.","\u0627\u0645\u062a\u0646\u0639 \u0627\u0644\u064a\u0648\u0645 \u0639\u0646 \u0627\u0644\u062d\u062f\u064a\u062b \u0639\u0646 \u0623\u064a \u0634\u062e\u0635 \u0641\u064a \u063a\u064a\u0627\u0628\u0647."],t.s)
B.aBT=s(["\u0627\u0628\u062a\u0633\u0645 \u0644\u0643\u0644 \u0634\u062e\u0635 \u062a\u0642\u0627\u0628\u0644\u0647 \u0627\u0644\u064a\u0648\u0645.","\u0627\u0641\u0639\u0644 \u0634\u064a\u0626\u064b\u0627 \u062a\u062d\u0628\u0647 \u0644\u0645\u062f\u0629 \u0639\u0634\u0631\u064a\u0646 \u062f\u0642\u064a\u0642\u0629\u060c \u0644\u0646\u0641\u0633\u0643 \u0641\u0642\u0637.","\u0627\u0643\u062a\u0628 \u062e\u0645\u0633\u0629 \u0623\u0634\u064a\u0627\u0621 \u0628\u0633\u064a\u0637\u0629 \u062a\u0633\u0639\u062f\u0643.","\u062a\u0648\u0642\u0651\u0641 \u0639\u0646 \u0645\u0642\u0627\u0631\u0646\u0629 \u0646\u0641\u0633\u0643 \u0628\u0627\u0644\u0622\u062e\u0631\u064a\u0646 \u0637\u0648\u0627\u0644 \u0627\u0644\u064a\u0648\u0645."],t.s)
